 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # The repeated isolated color marks the locations at which to stamp the
    # exemplar. The exemplar itself is the largest connected non-background
    # component after excluding that marker color.
    marker_candidates = []
    for color, count in counts.items():
        if color == bg or count < 2:
            continue
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if all(
            all(
                (dr == 0 and dc == 0)
                or not (0 <= r + dr < h and 0 <= c + dc < w)
                or grid[r + dr][c + dc] == bg
                for dr in (-1, 0, 1)
                for dc in (-1, 0, 1)
            )
            for r, c in pts
        ):
            marker_candidates.append((count, color, pts))
    if not marker_candidates:
        return [row[:] for row in grid]
    _, marker, anchors = max(marker_candidates)

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or grid[r][c] == marker or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] != bg and grid[nr][nc] != marker and
                            (nr, nc) not in seen):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(comp)
    if not components:
        return [row[:] for row in grid]
    exemplar = max(components, key=len)
    r0 = min(r for r, c in exemplar)
    r1 = max(r for r, c in exemplar)
    c0 = min(c for r, c in exemplar)
    c1 = max(c for r, c in exemplar)
    template = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    ar, ac = (r1 - r0) // 2, (c1 - c0) // 2

    out = [row[:] for row in grid]
    for mr, mc in anchors:
        top, left = mr - ar, mc - ac
        for tr in range(len(template)):
            for tc in range(len(template[0])):
                rr, cc = top + tr, left + tc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = template[tr][tc]
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
